+	case contentNodeIs:
+		if len(v) == 0 {
+			panic("empty contentNodeIs")
+		}
+		vv := v[lidx]
+		if vv != nil {
+			return vv, true, accuracy
+		}
+		return nil, false, 0
+	case resourceSources:
+		vv := v[lidx]
+		if vv != nil {
+			return vv, true, doctree.DimensionLanguage
+		}
+		if exact {
+			return nil, false, 0
+		}
+		// For non content resources, pick the first match.
+		for _, vv := range v {
+			if vv != nil {
+				if vv.isPage() {
+					return nil, false, 0
+				}
+				return vv, true, 0
+			}
+		}
+	case *resourceSource:
+		if s.LangIndex(v) == lidx {
+			return v, true, doctree.DimensionLanguage
+		}
+		if !v.isPage() && !exact {
+			return v, true, 0
+		}
+	case *pageState:
+		if s.LangIndex(v) == lidx {
+			return n, true, doctree.DimensionLanguage
+		}
+	default:
+		panic(fmt.Sprintf("unknown type %T", n))
+	}
+	return nil, false, 0
+}
+
+func (s *contentNodeShifter) ForEeachInDimension(n contentNodeI, d int, f func(contentNodeI) bool) {
+	if d != doctree.DimensionLanguage.Index() {
+		panic("only language dimension supported")
+	}
+
+	switch vv := n.(type) {
+	case contentNodeIs:
+		for _, v := range vv {
+			if v != nil {
+				if f(v) {
+					return
+				}
+			}
+		}
+	default:
+		f(vv)
+	}
+}
+
+func (s *contentNodeShifter) InsertInto(old, new contentNodeI, dimension doctree.Dimension) contentNodeI {
+	langi := dimension[doctree.DimensionLanguage.Index()]
+	switch vv := old.(type) {
+	case *pageState:
+		newp, ok := new.(*pageState)
+		if !ok {
+			panic(fmt.Sprintf("unknown type %T", new))
+		}
+		if s.LangIndex(vv) == s.LangIndex(newp) && s.LangIndex(newp) == langi {
+			return new
+		}
+		is := make(contentNodeIs, s.numLanguages)
+		is[s.LangIndex(vv)] = old
+		is[langi] = new
+		return is
+	case contentNodeIs:
+		vv[langi] = new
+		return vv
+	case resourceSources:
+		vv[langi] = new.(*resourceSource)
+		return vv
+	case *resourceSource:
+		newp, ok := new.(*resourceSource)
+		if !ok {
+			panic(fmt.Sprintf("unknown type %T", new))
+		}
+		if s.LangIndex(vv) == s.LangIndex(newp) && s.LangIndex(newp) == langi {
+			return new
+		}
+		rs := make(resourceSources, s.numLanguages)
+		rs[s.LangIndex(vv)] = vv
+		rs[langi] = newp
+		return rs
+
+	default:
+		panic(fmt.Sprintf("unknown type %T", old))
+	}
+}
+
+func (s *contentNodeShifter) Insert(old, new contentNodeI) contentNodeI {
+	switch vv := old.(type) {
+	case *pageState:
+		newp, ok := new.(*pageState)
+		if !ok {
+			panic(fmt.Sprintf("unknown type %T", new))
+		}
+		if s.LangIndex(vv) == s.LangIndex(newp) {
+			return new
+		}
+		is := make(contentNodeIs, s.numLanguages)
+		is[s.LangIndex(newp)] = new
+		is[s.LangIndex(vv)] = old
+		return is
+	case contentNodeIs:
+		newp, ok := new.(*pageState)
+		if !ok {
+			panic(fmt.Sprintf("unknown type %T", new))
+		}
+		resource.MarkStale(vv[s.LangIndex(newp)])
+		vv[s.LangIndex(newp)] = new
+		return vv
+	case *resourceSource:
+		newp, ok := new.(*resourceSource)
+		if !ok {
+			panic(fmt.Sprintf("unknown type %T", new))
+		}
+		if s.LangIndex(vv) == s.LangIndex(newp) {
+			return new
+		}
+		rs := make(resourceSources, s.numLanguages)
+		rs[s.LangIndex(newp)] = newp
+		rs[s.LangIndex(vv)] = vv
+		return rs
+	case resourceSources:
+		newp, ok := new.(*resourceSource)
+		if !ok {
+			panic(fmt.Sprintf("unknown type %T", new))
+		}
+		resource.MarkStale(vv[s.LangIndex(newp)])
+		vv[s.LangIndex(newp)] = newp
+		return vv
+	default:
+		panic(fmt.Sprintf("unknown type %T", old))
+	}
+}
