+			if nn == nil {
+				m := &pageMeta{
+					s:        sa.Site,
+					pathInfo: pth,
+				}
+
+				ps, pth, err := sa.h.newPage(m)
+				if err != nil {
+					return false, err
+				}
+				w.Tree.InsertIntoValuesDimension(pth.Base(), ps)
+			}
+
+			// /a/b, we don't need to walk deeper.
+			if strings.Count(s, "/") > 1 {
+				w.SkipPrefix(s + "/")
+			}
