+	return nil
+}
+
+func (sa *sitePagesAssembler) addMissingTaxonomies() error {
+	if sa.pageMap.cfg.taxonomyDisabled && sa.pageMap.cfg.taxonomyTermDisabled {
+		return nil
+	}
+
+	tree := sa.pageMap.treePages
+
+	commit := tree.Lock(true)
+	defer commit()
